import{_ as e,o as a,c as i,a2 as o}from"./chunks/framework.DHmNT4rz.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1784470733000}'),r={name:"guide/introduction.md"};function n(s,t,d,l,c,u){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>SaaSWeave is a production-oriented, multi-tenant SaaS starter built as a full-stack TypeScript monorepo. It combines TanStack Start, Hono, oRPC, Drizzle ORM, Better Auth, BullMQ, Redis, and Paraglide.js behind one typed application boundary.</p><p>The repository is intended for teams building a hosted product with workspaces, billing, background processing, administration, and operational controls already connected. The internal workspace packages use the <code>@saasweave/*</code> scope consistently across apps, libraries, and tooling.</p><h2 id="what-is-included" tabindex="-1">What is included <a class="header-anchor" href="#what-is-included" aria-label="Permalink to &quot;What is included&quot;">​</a></h2><ul><li>Workspace tenancy with member roles, invitations, profiles, and organization switching</li><li>Email/password authentication, OAuth provider discovery, 2FA, SSO/SAML, sessions, and impersonation policy</li><li>Workspace console for billing, usage, API keys, webhooks, notifications, audit history, exports, and security settings</li><li>Platform administration for users, workspaces, plans, feature rollout, analytics, email, maintenance mode, and audit events</li><li>Stripe checkout, portal, webhook ordering, subscriptions, usage attribution, and MRR snapshots</li><li>BullMQ workers for email, notifications, webhooks, Stripe, data exports, batch jobs, and schedules</li><li>PostgreSQL persistence through Drizzle schema and checked-in migrations</li><li>Redis-backed cache, rate limits, queues, readiness, and queue metrics</li><li>S3-compatible media storage through MinIO, a local-disk fallback, and optional imgproxy delivery</li><li>Paraglide localization, SEO helpers, sitemap generation, transactional email templates, and a shared UI package</li><li>Structured logs, Prometheus metrics, health probes, retention jobs, and backup verification tools</li></ul><p>Most integrations are environment-gated. Stripe, OAuth, external email delivery, OpenAPI docs, metrics, and the local SAML identity provider remain off until configured.</p><h2 id="the-stack" tabindex="-1">The stack <a class="header-anchor" href="#the-stack" aria-label="Permalink to &quot;The stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Technology</th></tr></thead><tbody><tr><td>Web</td><td>React 19, TanStack Start and Router, TanStack Query, Tailwind CSS</td></tr><tr><td>API</td><td>Hono, oRPC, OpenAPI</td></tr><tr><td>Auth</td><td>Better Auth, organization, 2FA, SSO, OAuth</td></tr><tr><td>Data</td><td>PostgreSQL 18, Drizzle ORM</td></tr><tr><td>Async</td><td>Redis 8, BullMQ</td></tr><tr><td>Storage</td><td>MinIO/S3-compatible storage, local disk, imgproxy</td></tr><tr><td>Localization</td><td>Paraglide.js</td></tr><tr><td>Tooling</td><td>Vite Plus, pnpm workspaces, Vitest, Playwright, Oxfmt, Oxlint</td></tr><tr><td>Deployment</td><td>Multi-stage Docker images, Docker Compose, Coolify Compose</td></tr></tbody></table><h2 id="who-it-is-for" tabindex="-1">Who it is for <a class="header-anchor" href="#who-it-is-for" aria-label="Permalink to &quot;Who it is for&quot;">​</a></h2><p>This is a starter framework, not a finished product. It gives a team the undifferentiated operational machinery of a SaaS (tenancy, auth, billing, queues, observability) so the work that remains is the product itself.</p><p>Read on:</p><ul><li><a href="/SaaSWeave/guide/getting-started">Quick start</a> runs the full stack locally with Docker.</li><li><a href="/SaaSWeave/guide/architecture">Architecture</a> explains how the apps and packages fit together.</li><li><a href="/SaaSWeave/tour">Product tour</a> is a visual walkthrough of every surface.</li></ul>',12)])])}const m=e(r,[["render",n]]);export{p as __pageData,m as default};
